return items.map((item) => {
  const source = item.json || {};
  const payload = source.downstream_payload && typeof source.downstream_payload === 'object'
    ? source.downstream_payload
    : source;
  let state = {};
  try { state = JSON.parse(payload.after_payload_json || '{}'); } catch (_error) {}
  return { json: {
    ...payload,
    should_escalate: payload.should_escalate ?? state.should_escalate ?? false,
    escalation_reason: payload.escalation_reason ?? state.escalation_reason ?? null,
    inbound_event_id: source.inbound_event_id || payload.inbound_event_id || null,
    processing_token: source.processing_token || payload.processing_token || null,
  } };
});

const row = items[0]?.json ?? {};
const parsedLeadId = Number(row.lead_id);
const leadId = Number.isSafeInteger(parsedLeadId) && parsedLeadId > 0 ? parsedLeadId : null;
const assigned = row.assignment_result === 'assigned' && Boolean(row.assigned_seller_id);
if (!leadId || !row.conversation_id || !row.phone_number) {
  return [{ json: { ...row, should_send_handoff: false, message: null, response_text: null, lead_id: null } }];
}
const message = assigned
  ? 'Gracias, ya registré tu solicitud y quedó asignada al equipo comercial. Una ejecutiva revisará los antecedentes para preparar una cotización acorde a tu proyecto.'
  : 'Gracias, ya registré tu solicitud. El equipo comercial podrá revisar el caso sin que tengas que repetir la información.';
return [{ json: {
  ...row,
  should_send_handoff: true,
  message,
  response_text: message,
  response_kind: assigned ? 'handoff_confirmed' : 'handoff_registered_unassigned',
  lead_id: leadId,
} }];

const row = items[0]?.json ?? {};

const OPERATIONAL_INTENTS = new Set([
  'complaint',
  'warranty_inquiry',
  'payment_proof',
  'invoice_request',
]);

const conversationId = Number(row.conversation_id);
const hasConversation = Number.isSafeInteger(conversationId) && conversationId > 0;
const phoneNumber = String(row.phone_number || '').trim();

const intent = String(row.intent || '').trim();
const isOperational = OPERATIONAL_INTENTS.has(intent);

const shouldWrite = hasConversation && Boolean(phoneNumber) && !isOperational;

const commercialBlocked = Array.isArray(row.commercial_missing_fields)
  && row.commercial_missing_fields.length > 0;

const qualified = Boolean(row.should_create_lead)
  && !commercialBlocked
  && row.confirmation_status === 'confirmed';

const requestedStatus = qualified ? 'qualified' : 'new';

return [
  {
    json: {
      ...row,
      opportunity_scope: {
        conversation_id: conversationId,
        phone_number: phoneNumber,
        source_number_id: Number(row.source_number_id) > 0 ? Number(row.source_number_id) : null,
        external_contact_id: row.external_contact_id || null,
        whatsapp_name: row.whatsapp_name || null,
        service: row.service || null,
        city: row.city || null,
        requirement: row.requirement || null,
        intent_code: intent || null,
        inbound_event_id: Number(row.inbound_event_id) > 0 ? Number(row.inbound_event_id) : null,
      },
      opportunity_write: shouldWrite,
      opportunity_status: requestedStatus,
      opportunity_skipped: !shouldWrite,
    },
  },
];

// =============================================================================
// Ensure Escalation Handoff — Unidad 3: escalamiento humano durable (P0).
// -----------------------------------------------------------------------------
// Nodo del dispatcher "WA - Inbound Downstream Dispatcher". SOURCE OF TRUTH
// del routing motivo->area->prioridad->responsable (PRD #22/#23/#9.5/#11) y
// del gate de no-cierre de intenciones operativas (PRD #22.16/#31.7).
//
// El mismo archivo es, en pruebas (harness), un modulo Node: expone
// HANDOFF_ROUTING, routeEscalation, evaluateClosureGate y buildIdempotencyKey
// para los tests de contrato. En n8n (Code node) solo se ejecuta la seccion
// final que lee `items`. Single source of truth: el fixture se reinyecta al
// workflow con tests/scripts/sync-workflow-nodes.mjs.
//
// Idempotency key: `{conversation_id}:{motivo}:{trigger}` — el trigger es el
// motivo textual normalizado (o 'intent:<codigo>'), de modo que un replay del
// mismo evento no duplica y un motivo distinto abre un handoff propio.
//
// Precedencia de routing (memoria #679):
// opt-out/abandono → humano → escalación/terminal → operacional → re-engagement → comercial/IA
// =============================================================================

const HANDOFF_ROUTING = {
  // PRECEDENCIA 1: opt-out/abandono
  opt_out: { area: 'claims', area_label: 'Reclamos', prioridad: 'urgente', responsable: 'Responsable de Reclamos' },
  abandoned: { area: 'sales', area_label: 'Ventas', prioridad: 'media', responsable: 'Ejecutiva comercial' },

  // PRECEDENCIA 2: humano (solicitud explícita de persona)
  talk_human: { area: 'sales', area_label: 'Ventas', prioridad: 'alta', responsable: 'Ejecutiva comercial' },

  // PRECEDENCIA 3: escalación/terminal
  frustration: { area: 'sales', area_label: 'Ventas', prioridad: 'alta', responsable: 'Ejecutiva comercial' },
  high_urgency: { area: 'sales', area_label: 'Ventas', prioridad: 'alta', responsable: 'Ejecutiva comercial' },
  large_project: { area: 'sales', area_label: 'Ventas', prioridad: 'alta', responsable: 'Ejecutiva comercial' },
  complex_installation: { area: 'sales', area_label: 'Ventas', prioridad: 'alta', responsable: 'Ejecutiva comercial' },
  complaint: { area: 'claims', area_label: 'Reclamos', prioridad: 'urgente', responsable: 'Responsable de Reclamos' },
  discount: { area: 'management', area_label: 'Gerencia', prioridad: 'alta', responsable: 'Gerencia' },
  special_payment_condition: { area: 'management', area_label: 'Gerencia', prioridad: 'alta', responsable: 'Gerencia' },

  // PRECEDENCIA 4: operacional
  scheduling_change: { area: 'scheduling', area_label: 'Programación', prioridad: 'media', responsable: 'Programación (despacho/instalación)' },
  committed_issue: { area: 'scheduling', area_label: 'Programación', prioridad: 'alta', responsable: 'Programación (despacho/instalación)' },
  stock_confirm: { area: 'sales', area_label: 'Ventas', prioridad: 'media', responsable: 'Ejecutiva comercial' },
  photos_eval: { area: 'sales', area_label: 'Ventas', prioridad: 'media', responsable: 'Ejecutiva comercial' },
  payment_proof: { area: 'finance', area_label: 'Finanzas', prioridad: 'alta', responsable: 'Finanzas' },
  invoice: { area: 'finance', area_label: 'Finanzas', prioridad: 'media', responsable: 'Finanzas / Administración' },
  warranty: { area: 'post_sale', area_label: 'Postventa', prioridad: 'alta', responsable: 'Administración / Postventa' },
  post_sale: { area: 'post_sale', area_label: 'Postventa', prioridad: 'media', responsable: 'Administración / Postventa' },

  // PRECEDENCIA 5: re-engagement
  loop: { area: 'sales', area_label: 'Ventas', prioridad: 'media', responsable: 'Ejecutiva comercial' },
  reengagement: { area: 'sales', area_label: 'Ventas', prioridad: 'media', responsable: 'Ejecutiva comercial' },

  // PRECEDENCIA 6: comercial/IA (B2B)
  b2b: { area: 'b2b', area_label: 'B2B', prioridad: 'alta', responsable: 'Patricia / Área B2B' },
  purchase_order: { area: 'b2b', area_label: 'B2B', prioridad: 'alta', responsable: 'Patricia / Área B2B' },
};

// Fallback determinista por area declarada por la AI (contrato del advisor).
const AREA_FALLBACK = {
  sales: { area: 'sales', area_label: 'Ventas', prioridad: 'alta', responsable: 'Ejecutiva comercial' },
  b2b: { area: 'b2b', area_label: 'B2B', prioridad: 'alta', responsable: 'Patricia / Área B2B' },
  finance: { area: 'finance', area_label: 'Finanzas', prioridad: 'alta', responsable: 'Finanzas' },
  post_sale: { area: 'post_sale', area_label: 'Postventa', prioridad: 'media', responsable: 'Administración / Postventa' },
  claims: { area: 'claims', area_label: 'Reclamos', prioridad: 'urgente', responsable: 'Responsable de Reclamos' },
  scheduling: { area: 'scheduling', area_label: 'Programación', prioridad: 'media', responsable: 'Programación (despacho/instalación)' },
  management: { area: 'management', area_label: 'Gerencia', prioridad: 'alta', responsable: 'Gerencia' },
};

const DEFAULT_ROUTING = { area: 'sales', area_label: 'Ventas', prioridad: 'media', responsable: 'Ejecutiva comercial' };

const INTENT_TO_MOTIVE = {
  talk_to_human: 'talk_human',
  complaint: 'complaint',
  warranty_inquiry: 'warranty',
  payment_proof: 'payment_proof',
  invoice_request: 'invoice',
  b2b_request: 'b2b',
  purchase_order: 'purchase_order',
  discount_request: 'discount',
  reschedule_delivery: 'scheduling_change',
  reschedule_installation: 'scheduling_change',
  post_sale: 'post_sale',
  stock_inquiry: 'stock_confirm',
  returning_customer: 'loop',
  review: 'loop',
  opt_out: 'opt_out',           // PRECEDENCIA 1
  abandoned_conversation: 'abandoned', // PRECEDENCIA 1
  frustration_detected: 'frustration', // PRECEDENCIA 3
  loop_detected: 'loop',        // PRECEDENCIA 5
  reengagement_detected: 'reengagement', // PRECEDENCIA 5
};

// Motivo por señales de texto del reason de escalamiento (PRD #22 triggers).
// Ordenado por PRECEDENCIA (primero = mayor precedencia)
const REASON_TO_MOTIVE = [
  // PRECEDENCIA 1: opt-out/abandono
  ['opt_out', /no me escribas|escribas mas|dame de baja|baja.*(pas|mensajes|programa)|\bstop\b|no quiero.*mensajes|dej.*escribirme|no me envies|darme de baja|quitarme|no me molestes|opt.?out/i],
  ['abandoned', /ya no (me )?(interesa|necesito|quiero)|lo pense|estoy con (la )?(otra|competencia)|no voy a (comprar|avanzar)|cerremos/i],

  // PRECEDENCIA 2: humano
  ['talk_human', /hablar.*(persona|humano|ejecutiva|operador)|atencion humana|persona real|\bejecutiv\b|\boperador\b|\basesor\b|necesito (una|un) (ejecutiva|asesor|humano|operador|persona)/i],

  // PRECEDENCIA 3: escalación/terminal
  ['complaint', /reclamo|queja|molest|frustr|mala atencion|falla|roto|quebr|problema/i],
  ['frustration', /no me (estai|está|estas|estás|escuchas|entiendes)|no (escuchai|escucha|entendi)|que (lata|fome)|pesimo|mal servicio|no (sirve|funciona|gusta)|decepcionado|ayuda|no entiendo|que (hay|hace) (falta|que hacer)|quejarme|problema contigo/i],
  ['high_urgency', /urgent|para ayer|necesito (ya|ahora|urgente)/i],
  ['large_project', /2\.000\.000|dos millones|millon/i],
  ['complex_installation', /instalacion|coordinacion logistica|acceso/i],
  ['discount', /descuento|igualar|bajo el precio|rebaja/i],
  ['special_payment_condition', /condicion (especial|servicio de pago|pago a 30)/i],

  // PRECEDENCIA 4: operacional
  ['warranty', /garant/i],
  ['payment_proof', /comprobante|transferencia|abono|pago|pago enviado/i],
  ['invoice', /factur/i],
  ['scheduling_change', /reagend|cambio de fecha|fecha/i],
  ['committed_issue', /despacho|programada|programado|pedido comprometido/i],
  ['stock_confirm', /stock|disponibilidad/i],
  ['photos_eval', /foto|fotos|imagen/i],

  // PRECEDENCIA 5: re-engagement
  ['loop', /(no me (estai|está|estas|estás)|no (escuchai|escucha|entendi|entiendes)).*(repet|otra vez|de nuevo)|(repet|otra vez|de nuevo).*(no me|no escucha|no entendi)/i],
  ['reengagement', /hola de nuevo|volvi|volví|retomar|seguir.*anterior|la anterior|misma solicitud|misma cotizacion/i],

  // PRECEDENCIA 6: comercial/IA (B2B)
  ['b2b', /b2b|empresa|constructora|inmobiliaria|licitacion|proveedor|volumen/i],
  ['purchase_order', /orden de compra|\boc\b/i],
];

const normalizeReason = (value) => String(value ?? '').trim().replace(/\s+/g, ' ').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

const motiveFromReason = (reason) => {
  const text = normalizeReason(reason);
  if (!text) return null;
  for (const [motive, pattern] of REASON_TO_MOTIVE) {
    if (pattern.test(text)) return motive;
  }
  return null;
};

// =============================================================================
// Precedence resolver: dado un conjunto de motivos candidatos, devuelve el de
// mayor precedencia según el orden: opt-out/abandono → humano → escalación/terminal
// → operacional → re-engagement → comercial/IA
// =============================================================================
const PRECEDENCE_ORDER = [
  'opt_out',
  'abandoned',
  'talk_human',
  'complaint',
  'frustration',
  'high_urgency',
  'large_project',
  'complex_installation',
  'discount',
  'special_payment_condition',
  'warranty',
  'payment_proof',
  'invoice',
  'scheduling_change',
  'committed_issue',
  'stock_confirm',
  'photos_eval',
  'post_sale',
  'loop',
  'reengagement',
  'b2b',
  'purchase_order',
];

const resolvePrecedence = (motives) => {
  if (!motives || motives.length === 0) return null;
  for (const motive of PRECEDENCE_ORDER) {
    if (motives.includes(motive)) return motive;
  }
  return motives[0]; // fallback to first if not in precedence list
};

const routeEscalation = (row) => {
  const conversationId = Number(row.conversation_id);
  const hasConversation = Number.isSafeInteger(conversationId) && conversationId > 0;
  const phoneNumber = String(row.phone_number || '').trim();
  const shouldEscalate = Boolean(row.should_escalate) || Boolean(row.escalation_required);
  const area = String(row.escalation_area || '').trim();
  const aiRequestsOperational = Boolean(area && area !== 'none' && area !== 'sales');
  const escalated = shouldEscalate || aiRequestsOperational;

  if (!escalated || !hasConversation || !phoneNumber) {
    return {
      escalated: false,
      write: false,
      motivo: null,
      routing: null,
      idempotency_key: null,
      trigger: null,
      precedence_level: null,
      all_candidate_motives: [],
    };
  }

  const intent = String(row.intent || '').trim();
  const rawReason = String(row.escalation_reason || '').trim();
  const customerText = String(row.text_body || '').trim();
  const normalizedText = customerText.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  const isReengagement = Boolean(row.is_reengagement);
  const hasPendingFollowups = Boolean(row.has_pending_followups);

  // Collect ALL candidate motives from different sources
  const candidateMotives = new Set();

  // 1. From raw reason text (highest signal)
  const reasonMotive = motiveFromReason(rawReason);
  if (reasonMotive) candidateMotives.add(reasonMotive);

  // 2. From AI intent
  const intentMotive = INTENT_TO_MOTIVE[intent];
  if (intentMotive) candidateMotives.add(intentMotive);

  // 3. From AI declared area
  if (area && area !== 'none') candidateMotives.add(area);

  // 4. From conversation context: re-engagement
  if (isReengagement) {
    if (hasPendingFollowups) candidateMotives.add('reengagement');
    else candidateMotives.add('loop');
  }

  // 5. From frustration/loop detection in conversation orchestrator
  if (row.escalation_reason === 'frustration_detected') candidateMotives.add('frustration');
  if (row.escalation_reason === 'loop_detected') candidateMotives.add('loop');

  // 6. From opt-out/abandoned detection
  const optOutPatterns = [/no me escribas|escribas mas|dame de baja|baja.*(pas|mensajes|programa)|\bstop\b|no quiero.*mensajes|dej.*escribirme|no me envies|darme de baja|quitarme|no me molestes|opt.?out/i];
  const abandonedPatterns = [/ya no (interesa|necesito|quiero)|lo pense|estoy con (otra|competencia)|no voy a (comprar|avanzar)|cerremos/i];
  if (optOutPatterns.some(p => p.test(normalizedText))) candidateMotives.add('opt_out');
  if (abandonedPatterns.some(p => p.test(normalizedText))) candidateMotives.add('abandoned');

  // Resolve to highest precedence motive
  const allCandidates = Array.from(candidateMotives);
  const resolvedMotive = resolvePrecedence(allCandidates);

  const routing = HANDOFF_ROUTING[resolvedMotive] || AREA_FALLBACK[area] || DEFAULT_ROUTING;
  const trigger = rawReason || (intent ? `intent:${intent}` : routing.area);

  // Determine precedence level for logging
  const precedenceLevel = PRECEDENCE_ORDER.indexOf(resolvedMotive) + 1;

  return {
    escalated: true,
    write: true,
    motivo: resolvedMotive || routing.area,
    routing,
    trigger,
    idempotency_key: buildIdempotencyKey(conversationId, resolvedMotive || routing.area, trigger),
    precedence_level: precedenceLevel,
    all_candidate_motives: allCandidates,
  };
};

const buildIdempotencyKey = (conversationId, motivo, trigger) =>
  [conversationId, motivo, trigger].join(':');

// =============================================================================
// Gate de no-cierre (PRD #33.16, #33.8): ninguna intencion operativa
// (reclamo, garantia, comprobante, factura) ni B2B se cierra mientras el
// escalamiento no exista y este al menos 'notified'.
// =============================================================================
const OPERATIONAL_CLOSURE_INTENTS = new Set([
  'complaint',
  'warranty_inquiry',
  'payment_proof',
  'invoice_request',
  'b2b_request',
  'purchase_order',
]);

const NOTIFIED_OR_BETTER = new Set(['notified', 'acknowledged', 'resolved']);

const evaluateClosureGate = (input) => {
  const intent = String(input.intent || '').trim();
  const shouldEscalate = Boolean(input.should_escalate || input.escalation_required);
  const customerType = String(input.customer_type || '').trim();
  const leadClass = String(input.lead_class || '').trim();
  const operational = OPERATIONAL_CLOSURE_INTENTS.has(intent)
    || customerType === 'b2b'
    || leadClass === 'D';

  if (!operational || !shouldEscalate) {
    return {
      operational,
      requires_handoff: false,
      closure_allowed: true,
      required_status: null,
      reason: 'no_handoff_required',
      handoff_exists: false,
    };
  }

  const handoffExists = Boolean(input.handoff_exists);
  const handoffStatus = String(input.handoff_status || '').trim();
  if (!handoffExists) {
    return {
      operational,
      requires_handoff: true,
      closure_allowed: false,
      required_status: 'notified',
      reason: 'handoff_missing',
      handoff_exists: false,
    };
  }

  const ready = NOTIFIED_OR_BETTER.has(handoffStatus);
  return {
    operational,
    requires_handoff: true,
    closure_allowed: ready,
    required_status: 'notified',
    reason: ready ? 'handoff_notified' : 'handoff_pending',
    handoff_exists: true,
    handoff_status: handoffStatus,
  };
};

// =============================================================================
// Seccion n8n (Code node): procesa el item de entrada del dispatcher.
// En Node (harness) `items` no existe y este bloque no se ejecuta.
// =============================================================================
if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    HANDOFF_ROUTING,
    AREA_FALLBACK,
    DEFAULT_ROUTING,
    motiveFromReason,
    routeEscalation,
    buildIdempotencyKey,
    evaluateClosureGate,
    OPERATIONAL_CLOSURE_INTENTS,
    PRECEDENCE_ORDER,
    resolvePrecedence,
    REASON_TO_MOTIVE,
    INTENT_TO_MOTIVE,
  };
}

if (typeof items !== 'undefined') {
  const row = items[0]?.json ?? {};
  const resolution = routeEscalation(row);
  const gate = evaluateClosureGate({
    intent: row.intent,
    should_escalate: resolution.escalated,
    customer_type: row.customer_type,
    lead_class: row.lead_class,
    handoff_exists: row.declared_handoff_exists === true && resolution.escalated,
    handoff_status: row.declared_handoff_status || row.handoff_status || 'pending',
  });

  return [
    {
      json: {
        ...row,
        handoff_write: resolution.write,
        handoff_skipped: !resolution.write,
        handoff_scope: {
          conversation_id: Number(row.conversation_id) > 0 ? Number(row.conversation_id) : null,
          phone_number: String(row.phone_number || '').trim() || null,
          source_number_id: Number(row.source_number_id) > 0 ? Number(row.source_number_id) : null,
          inbound_event_id: Number(row.inbound_event_id) > 0 ? Number(row.inbound_event_id) : null,
          motivo: resolution.motivo,
          area: resolution.routing?.area ?? null,
          area_label: resolution.routing?.area_label ?? null,
          prioridad: resolution.routing?.prioridad ?? null,
          responsable: resolution.routing?.responsable ?? null,
          idempotency_key: resolution.idempotency_key,
          trigger: resolution.trigger,
          escalation_reason: String(row.escalation_reason || '').trim() || null,
          escalation_area: String(row.escalation_area || '').trim() || null,
          intent: String(row.intent || '').trim() || null,
          estado: 'pending',
        },
        handoff_gate: gate,
        // Structured logging for precedence resolution (memoria #679)
        handoff_precedence_level: resolution.precedence_level,
        handoff_candidate_motives: resolution.all_candidate_motives,
        handoff_resolved_motive: resolution.motivo,
      },
    },
  ];
}

const source = $('Ensure Escalation Handoff').first().json;
const result = items[0]?.json ?? {};
return [{ json: { ...source, ...result, escalation_lane_complete: true } }];

// Build the durable metadata record for inbound media. Downloading happens only
// through Evolution's fixed internal getBase64FromMediaMessage endpoint.

const MEDIA_POLICY = {
  allowed_types: ['image', 'document', 'audio', 'video'],
  max_bytes: {
    image: 25 * 1024 * 1024,
    document: 25 * 1024 * 1024,
    audio: 25 * 1024 * 1024,
    video: 50 * 1024 * 1024,
  },
};

const normalizeSize = (value) => {
  if (value === undefined || value === null || value === '') return null;
  const parsed = Number(value);
  return Number.isSafeInteger(parsed) && parsed >= 0 ? parsed : null;
};

const evaluateMediaPolicy = (row, policy = MEDIA_POLICY) => {
  const type = String(row.attachment_type || '').trim().toLowerCase();
  if (!type) return { decision: 'skipped', reason: 'no_media', max_bytes: null };
  if (!policy.allowed_types.includes(type)) {
    return { decision: 'rejected', reason: 'unsupported_type', max_bytes: null };
  }
  const maxBytes = policy.max_bytes[type];
  const declaredSize = normalizeSize(row.file_size);
  if (declaredSize !== null && declaredSize > maxBytes) {
    return { decision: 'rejected', reason: 'oversized_declared', max_bytes: maxBytes };
  }
  return { decision: 'proceed', reason: null, max_bytes: maxBytes };
};

const buildMediaDedupeKey = (row) => {
  const mediaKey = String(row.media_key || row.external_media_id || '').trim();
  if (mediaKey) return `media:${mediaKey}`;
  const messageId = String(row.external_message_id || row.message_id || '').trim();
  return messageId ? `message:${messageId}` : null;
};

const parseRawPayload = (row) => {
  if (row.raw_payload && typeof row.raw_payload === 'object') return { value: row.raw_payload, error: null };
  if (typeof row.raw_payload_json !== 'string' || !row.raw_payload_json.trim()) {
    return { value: {}, error: 'raw_payload_missing' };
  }
  try {
    const parsed = JSON.parse(row.raw_payload_json);
    return parsed && typeof parsed === 'object'
      ? { value: parsed, error: null }
      : { value: {}, error: 'raw_payload_invalid' };
  } catch (_error) {
    return { value: {}, error: 'raw_payload_invalid' };
  }
};

const mediaScopeFor = (row, env = {}) => {
  const policy = {
    allowed_types: MEDIA_POLICY.allowed_types,
    max_bytes: { ...MEDIA_POLICY.max_bytes },
  };
  for (const type of policy.allowed_types) {
    const configured = Number(env[`MEDIA_MAX_BYTES_${type.toUpperCase()}`]);
    if (Number.isSafeInteger(configured) && configured > 0) policy.max_bytes[type] = configured;
  }

  const evaluation = evaluateMediaPolicy(row, policy);
  const parsedPayload = parseRawPayload(row);
  const payloadRejected = evaluation.decision === 'proceed' && parsedPayload.error;
  const conversationId = Number(row.conversation_id);
  const inboundEventId = Number(row.inbound_event_id);
  const sourceNumberId = Number(row.source_number_id);

  return {
    ...row,
    media_write: evaluation.decision !== 'skipped',
    media_skipped: evaluation.decision === 'skipped',
    media_scope: {
      media_key: String(row.media_key || row.external_media_id || '').trim() || null,
      external_url: String(row.external_url || '').trim() || null,
      message_id: String(row.external_message_id || row.message_id || '').trim() || null,
      inbound_event_id: Number.isSafeInteger(inboundEventId) && inboundEventId > 0 ? inboundEventId : null,
      conversation_id: Number.isSafeInteger(conversationId) && conversationId > 0 ? conversationId : null,
      source_number_id: Number.isSafeInteger(sourceNumberId) && sourceNumberId > 0 ? sourceNumberId : null,
      instance_name: String(row.instance_name || '').trim() || null,
      phone_number: String(row.phone_number || '').trim() || null,
      attachment_type: String(row.attachment_type || '').trim().toLowerCase() || null,
      mime_type: String(row.mime_type || '').trim().toLowerCase() || null,
      filename: String(row.filename || '').trim() || null,
      file_size: normalizeSize(row.file_size),
      expected_sha256: String(row.sha256 || '').trim() || null,
      max_bytes: evaluation.max_bytes,
      dedupe_key: buildMediaDedupeKey(row),
      raw_payload: parsedPayload.value,
      download_state: evaluation.decision === 'rejected' || payloadRejected ? 'rejected' : 'pending',
      rejected_reason: payloadRejected ? parsedPayload.error : evaluation.reason,
      attach_pending: false,
      attached_to: null,
    },
  };
};

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { MEDIA_POLICY, normalizeSize, evaluateMediaPolicy, buildMediaDedupeKey, parseRawPayload, mediaScopeFor };
}

if (typeof items !== 'undefined') {
  return [{ json: mediaScopeFor(items[0]?.json ?? {}, $env ?? {}) }];
}

const OPT_OUT_PATTERNS = [
  /no me escribas mas/i,
  /escribas mas/i,
  /baja.*(de la lista|pas|mensajes|programa)/i,
  /\bstop\b/i,
  /no quiero (mas )?(mensajes|publicidad|informacion|seguir recibiendo)/i,
  /dej(?:a|en) de escribirme/i,
  /no me envies mas mensajes/i,
  /darme de baja/i,
  /quitarme de la lista/i,
  /no me molestes/i,
];

const LOST_PATTERNS = [
  /ya no (me interesa|necesito|quiero)/i,
  /lo pense y no (voy a|quiero)/i,
  /estoy con (otra|la competencia)/i,
  /no voy a (comprar|avanzar)/i,
  /cerremos el tema/i,
];

const matches = (patterns, text) => patterns.some((pattern) => pattern.test(String(text || '').trim()));
const detectOptOut = (text) => matches(OPT_OUT_PATTERNS, text);
const detectLostIntent = (text) => matches(LOST_PATTERNS, text);

const asPositiveInteger = (value) => {
  const parsed = Number(value);
  return Number.isSafeInteger(parsed) && parsed > 0 ? parsed : null;
};

const resolveInboundCreatedEpochMs = (row, explicitEpochMs = 0) => {
  const numeric = Number(explicitEpochMs || row.inbound_created_epoch_ms || 0);
  if (Number.isFinite(numeric) && numeric > 0) return numeric;

  const parsed = Date.parse(String(row.inbound_created_at || ''));
  return Number.isFinite(parsed) && parsed > 0 ? parsed : null;
};

const resolveInboundIdentity = (row) => {
  const inboundEventId = asPositiveInteger(row.inbound_event_id);
  if (inboundEventId) return { type: 'event', id: inboundEventId };

  const inboundMessageId = asPositiveInteger(row.message_id);
  if (inboundMessageId) return { type: 'message', id: inboundMessageId };

  return null;
};

// One persisted inbound applies the follow-up policy at most once to its target
// conversation. The action is intentionally absent from the key: a replay must
// not create another policy event if downstream classification changes.
const buildIdempotencyKey = (targetConversationId, inboundIdentity) => {
  if (!targetConversationId || !inboundIdentity) return null;
  return `follow-up-policy:${targetConversationId}:${inboundIdentity.type}:${inboundIdentity.id}`;
};

const resolveCancellationAction = (row, explicitEpochMs = 0) => {
  const targetConversationId = asPositiveInteger(
    row.target_conversation_id
      || row.follow_up_target_conversation_id
      || row.conversation_id,
  );
  const validConversation = Boolean(targetConversationId);
  const customerText = String(row.text_body || '').trim();
  const inboundMessageId = asPositiveInteger(row.message_id);
  const inboundEventId = asPositiveInteger(row.inbound_event_id);
  const inboundIdentity = resolveInboundIdentity(row);
  const inboundCreatedEpochMs = resolveInboundCreatedEpochMs(row, explicitEpochMs);
  const handoffWrite = Boolean(row.handoff_write || row.handoff_scope?.idempotency_key);
  const escalated = Boolean(row.should_escalate || row.escalation_required || handoffWrite);
  const closed = ['closed', 'inactive_timeout', 'handed_to_sales'].includes(String(row.conversation_status_code || ''));
  const optOut = detectOptOut(customerText);
  const lost = detectLostIntent(customerText);

  let action = validConversation ? 'cancel' : 'none';
  let cancelReason = validConversation ? 'client_replied' : 'no_conversation';
  if (optOut) {
    action = 'opt_out';
    cancelReason = 'opt_out';
  } else if (lost) {
    action = 'cancel';
    cancelReason = 'lost';
  } else if (escalated) {
    action = 'cancel';
    cancelReason = 'escalated';
  } else if (closed) {
    action = 'cancel';
    cancelReason = 'closed';
  }

  const responseText = String(row.response_text || '').trim();
  const firstDelayHours = Math.max(1, Number(row.follow_up_first_delay_hours || 24));
  const scheduleCandidate = validConversation
    && action === 'cancel'
    && cancelReason === 'client_replied'
    && responseText.length > 0
    && String(row.conversation_status_code || '') === 'waiting_user';
  const databaseCanResolveTimestamp = inboundIdentity?.type === 'event';
  const shouldSchedule = scheduleCandidate
    && Boolean(inboundIdentity)
    && (Boolean(inboundCreatedEpochMs) || databaseCanResolveTimestamp);
  const cycleKey = inboundIdentity
    ? `inbound:${inboundIdentity.type}:${inboundIdentity.id}`
    : null;

  return {
    follow_up_target_conversation_id: targetConversationId,
    follow_up_cancel_action: action,
    follow_up_cancel_reason: cancelReason,
    follow_up_source_text: customerText || null,
    follow_up_source_message_id: inboundMessageId,
    follow_up_should_schedule: shouldSchedule,
    follow_up_cycle_key: cycleKey,
    follow_up_motivo: 'lead_sin_respuesta',
    follow_up_scheduled_at: shouldSchedule
      && inboundCreatedEpochMs
      ? new Date(inboundCreatedEpochMs + firstDelayHours * 3600000).toISOString()
      : null,
    follow_up_schedule_skipped_reason: scheduleCandidate && !shouldSchedule
      ? 'missing_persisted_inbound_identity_or_timestamp'
      : null,
    follow_up_cancel_decided: Boolean(action && action !== 'none'),
    follow_up_idempotency_key: buildIdempotencyKey(targetConversationId, inboundIdentity),
    follow_up_inbound_created_epoch_ms: inboundCreatedEpochMs,
    follow_up_source_event_id: inboundEventId,
    follow_up_first_delay_hours: firstDelayHours,
  };
};

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    OPT_OUT_PATTERNS,
    LOST_PATTERNS,
    detectOptOut,
    detectLostIntent,
    resolveCancellationAction,
    resolveInboundCreatedEpochMs,
    resolveInboundIdentity,
    buildIdempotencyKey,
  };
}

if (typeof items !== 'undefined') {
  const firstDelayHours = Number($env.FOLLOW_UP_FIRST_DELAY_HOURS || 24);
  return items.map((item) => ({
    json: {
      ...item.json,
      ...resolveCancellationAction({
        ...item.json,
        follow_up_first_delay_hours: firstDelayHours,
      }),
    },
  }));
}

return items.map((item) => {
  const row = item.json || {};
  const payload = typeof row.dispatcher_payload === 'string' ? JSON.parse(row.dispatcher_payload) : (row.dispatcher_payload || {});
  return { json: { ...payload, media_id: row.media_id ?? null, media_registration_result: row.media_registration_result || null } };
});

const CONTRACT_MODES = new Set(['legacy', 'shadow', 'canary', 'enforce']);

const asObject = (value) => value && typeof value === 'object' && !Array.isArray(value) ? value : {};
const safe = (value, fallback = '') => String(value ?? fallback).trim();
const modeVersion = (mode) => ['canary', 'enforce'].includes(mode) ? 'v3' : 'legacy';
const normalizeMode = (value) => {
  const mode = safe(value, 'legacy').toLowerCase();
  return CONTRACT_MODES.has(mode) ? mode : 'legacy';
};

const normalizeActiveRoute = (value) => {
  const route = asObject(value);
  const mode = normalizeMode(route.mode ?? route.route_mode);
  const ruleId = safe(route.rule_id ?? route.route_rule_id);
  if (!ruleId) return null;
  return {
    mode,
    contract_version: safe(route.contract_version, modeVersion(mode)),
    rule_id: ruleId,
  };
};

const resolveConversationContractRoute = (turn, configuration = {}) => {
  const input = asObject(turn);
  const requestedMode = normalizeMode(configuration.mode);
  const requestedRuleId = safe(configuration.rule_id, `rollout:${requestedMode}`);
  const activeRoute = normalizeActiveRoute(input.active_route);
  const fixed = activeRoute || {
    mode: requestedMode,
    contract_version: modeVersion(requestedMode),
    rule_id: requestedRuleId,
  };
  const isV3 = fixed.contract_version === 'v3';
  return {
    schema: 'conversation_contract_route/v1',
    turn_id: safe(input.turn_id ?? input.inbound_event_id),
    mode: fixed.mode,
    contract_version: fixed.contract_version,
    rule_id: fixed.rule_id,
    route_replayed: Boolean(activeRoute),
    route_drift_detected: Boolean(activeRoute)
      && (activeRoute.mode !== requestedMode || activeRoute.rule_id !== requestedRuleId),
    shadow_requested: fixed.mode === 'shadow',
    visible_contract: fixed.mode === 'shadow' ? 'legacy' : fixed.contract_version,
    recovery_contract: isV3 ? 'v3' : 'legacy',
    legacy_reinterpretation_allowed: !isV3,
  };
};

const planShadowEvaluation = ({ route, legacy_delivery: legacyDelivery, payload }) => {
  const fixedRoute = asObject(route);
  const delivery = asObject(legacyDelivery);
  const source = asObject(payload);
  const dispatch = fixedRoute.mode === 'shadow' && delivery.delivered === true
    && Boolean(safe(delivery.receipt_ref));
  return {
    schema: 'ai_prd_shadow_dispatch/v1',
    dispatch,
    reason: dispatch ? 'post_delivery' : 'not_eligible',
    turn_id: safe(fixedRoute.turn_id),
    route_rule_id: safe(fixedRoute.rule_id),
    legacy_delivery_receipt_ref: safe(delivery.receipt_ref) || null,
    wait_for_completion: false,
    visible_latency_ms: 0,
    allow_mutations: false,
    allow_effects: false,
    payload: {
      ...source,
      shadow_mode: true,
      state_mutations: [],
      effect_requests: [],
      authorized_mutations: [],
      authorized_effect_requests: [],
    },
  };
};

const recordShadowEvaluation = (plan, outcome) => {
  const dispatch = asObject(plan);
  const result = asObject(outcome);
  const ok = result.ok === true;
  return {
    schema: 'ai_prd_shadow_audit/v1',
    turn_id: safe(dispatch.turn_id),
    route_rule_id: safe(dispatch.route_rule_id),
    legacy_delivery_receipt_ref: safe(dispatch.legacy_delivery_receipt_ref) || null,
    status: ok ? 'completed' : 'failed',
    error: ok ? null : safe(result.error, 'shadow_failed'),
    duration_ms: Math.max(0, Number(result.duration_ms || 0)),
    visible_delivery_affected: false,
    mutations_applied: 0,
    effects_executed: 0,
  };
};

const POLICY_FIELDS = [
  'name', 'product', 'service', 'commune', 'quantity', 'measurements', 'use_case',
  'modality', 'urgency', 'desired_date', 'terrain', 'truck_access',
  'debris_removal', 'customer_type', 'company', 'company_rut', 'contact_name',
  'contact_role', 'email', 'purchase_order', 'invoice_required', 'address',
  'access_restrictions', 'reception_contact', 'issue_description', 'payment_amount',
  'payment_method', 'quote_number',
];

const buildV3PolicyInput = (row, options = {}) => {
  const input = asObject(row);
  const context = asObject(input.qualification_context);
  const shadow = options.shadow === true || input.shadow_mode === true;
  const explicitGrounding = asObject(input.v3_grounding);
  const commercialContext = asObject(input.commercial_context);
  const catalogItems = Array.isArray(commercialContext.catalog_items) ? commercialContext.catalog_items : [];
  const refPart = (value) => safe(value).normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  const derivedCatalog = [];
  for (const item of catalogItems) {
    const name = safe(item?.name);
    if (!name) continue;
    const concept = safe(item?.item_type).toLowerCase() === 'service' ? 'service' : 'product';
    derivedCatalog.push({ ref: `${concept}:${refPart(item.id || item.sku || name)}`, concept, value: name });
    for (const city of Array.isArray(item?.applicable_cities) ? item.applicable_cities : []) {
      if (safe(city)) derivedCatalog.push({ ref: `commune:${refPart(city)}`, concept: 'commune', value: safe(city) });
    }
  }
  const grounding = {
    catalog: [
      ...(Array.isArray(explicitGrounding.catalog) ? explicitGrounding.catalog : []),
      ...derivedCatalog,
    ],
    modality_synonyms: Array.isArray(explicitGrounding.modality_synonyms)
      ? explicitGrounding.modality_synonyms
      : [
          { ref: 'modality:material', concept: 'modality', value: 'material' },
          { ref: 'modality:delivery', concept: 'modality', value: 'delivery' },
          { ref: 'modality:installation', concept: 'modality', value: 'installation' },
          { ref: 'modality:pickup', concept: 'modality', value: 'pickup' },
        ],
  };
  const facts = [];
  const goals = [];
  const allowedMutations = [];
  for (const field of POLICY_FIELDS) {
    const directValue = input[field];
    const value = context[field] ?? directValue;
    const hasValue = value !== undefined && value !== null && safe(value) !== '';
    const factId = hasValue ? `fact:${field}` : null;
    if (hasValue) {
      facts.push({
        fact_id: factId,
        field,
        value,
        mutability: 'customer_correctable',
        source: { message_id: safe(input.last_message_id), evidence_digest: safe(input.last_evidence_digest) },
      });
    }
    goals.push({
      goal_id: field,
      status: hasValue ? 'resolved' : 'unresolved',
      importance: ['product', 'commune', 'quantity', 'modality'].includes(field) ? 'required_for_effect' : 'optional',
      blocks_effects: ['product', 'commune', 'quantity', 'modality'].includes(field) ? ['create_lead'] : [],
    });
    if (!shadow) {
      allowedMutations.push(hasValue
        ? { operation: 'replace', concept: field, field, current_fact_id: factId }
        : { operation: 'set', concept: field, field });
    }
  }
  return {
    turn: {
      id: safe(input.inbound_event_id ?? input.turn_id),
      conversation_id: safe(input.conversation_id ?? input.target_conversation_id),
      conversation_revision: Number(input.conversation_revision || 0),
      message: {
        id: safe(input.external_message_id ?? input.inbound_event_id),
        text: safe(input.text_body ?? input.message_current),
      },
    },
    history: { messages: Array.isArray(input.recent_messages) ? input.recent_messages : [], truncated: false },
    facts,
    goals,
    allowed_mutations: allowedMutations,
    grounding,
    claim_rules: [
      { rule_id: 'no_stock_confirmation', kind: 'forbidden_pattern', pattern: '\\bstock\\s+(confirmado|disponible)\\b', flags: 'iu' },
      { rule_id: 'no_unreceipted_derivation', kind: 'forbidden_pattern', pattern: '\\b(ya|quedo)\\s+derivad[oa]\\b', flags: 'iu' },
    ],
    effect_permissions: shadow ? [] : [{ type: 'create_lead' }, { type: 'handoff' }],
    effect_requirements: shadow ? [] : [
      { effect_type: 'create_lead', required_goal_ids: ['product', 'commune', 'quantity', 'modality'] },
      { effect_type: 'handoff', required_goal_ids: [] },
    ],
  };
};

module.exports = {
  CONTRACT_MODES,
  resolveConversationContractRoute,
  planShadowEvaluation,
  recordShadowEvaluation,
  buildV3PolicyInput,
};


return items.map((item) => {
  const input = item.json || {};
  const plan = planShadowEvaluation({
    route: input.contract_route || {
      turn_id: input.inbound_event_id,
      mode: input.contract_mode || input.route_mode,
      rule_id: input.route_rule_id,
    },
    legacy_delivery: {
      delivered: input.outbound_lane_complete === true
        && (input.delivery_status === 'sent' || input.outbound_dispatch_status === 'already_sent'),
      receipt_ref: input.delivery_receipt_ref || input.outbound_message_id || input.external_message_id,
    },
    payload: input,
  });
  return { json: { ...input, shadow_plan: plan, shadow_dispatch: plan.dispatch, shadow_payload: plan.payload } };
});
